/**
 * Generate `lib/tutor/build/generated/katex-inline.ts`: KaTeX CSS for the walkthrough iframe with the WOFF2
 * fonts inlined as data URIs (task 3B-Q8/K1; the iframe CSP allows `font-src data:` and nothing else).
 * Only the fonts of ordinary school maths are inlined (see FONTS); a glyph of another family falls back to the
 * system serif font. Output is deterministic.
 *
 * Usage: node scripts/generate-tutor-katex.mjs [--check]
 *   --check  write nothing; exit 1 if the generated file is missing or differs.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import prettier from 'prettier';

const require = createRequire(import.meta.url);
const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const katexDir = path.dirname(require.resolve('katex/package.json'));
const version = require('katex/package.json').version;
const outFile = path.join(root, 'lib', 'tutor', 'build', 'generated', 'katex-inline.ts');
const check = process.argv.includes('--check');

/** Latin text, digits, operators, italic variables, AMS symbols (≤, ≥, ∈, ℝ), big delimiters, \mathcal, \mathsf. */
const FONTS = [
  'KaTeX_AMS-Regular',
  'KaTeX_Caligraphic-Regular',
  'KaTeX_Main-Bold',
  'KaTeX_Main-Italic',
  'KaTeX_Main-Regular',
  'KaTeX_Math-BoldItalic',
  'KaTeX_Math-Italic',
  'KaTeX_SansSerif-Regular',
  'KaTeX_Size1-Regular',
  'KaTeX_Size2-Regular',
];

const css = readFileSync(path.join(katexDir, 'dist', 'katex.min.css'), 'utf8');
const faces = [];
for (const [, body] of css.matchAll(/@font-face\{([^}]*)\}/g)) {
  const file = body.match(/url\(fonts\/([^)]+)\.woff2\)/)?.[1];
  if (!file || !FONTS.includes(file)) continue;
  const font = readFileSync(path.join(katexDir, 'dist', 'fonts', `${file}.woff2`));
  const pick = (re) => body.match(re)?.[0] ?? '';
  faces.push(
    `@font-face{${pick(/font-family:[^;]+/)};${pick(/font-style:[^;]+/)};${pick(/font-weight:[^;]+/)};font-display:block;src:url(data:font/woff2;base64,${font.toString('base64')}) format("woff2")}`,
  );
}
if (faces.length !== FONTS.length) {
  throw new Error(`expected ${FONTS.length} KaTeX faces, found ${faces.length}`);
}
const rules = css.replace(/@font-face\{[^}]*\}/g, '').trim();
const source = [
  '// GENERATED by scripts/generate-tutor-katex.mjs — do not edit',
  `// KaTeX ${version}, ${FONTS.length} WOFF2 fonts inlined`,
  `export const KATEX_INLINE_CSS = ${JSON.stringify(faces.join('') + rules)};`,
  '',
].join('\n');
const config = await prettier.resolveConfig(outFile);
const text = await prettier.format(source, { ...config, parser: 'typescript' });

if (check) {
  if (!existsSync(outFile) || readFileSync(outFile, 'utf8') !== text) {
    console.error('[tutor-katex] out of date (run: pnpm gen:tutor-katex)');
    process.exit(1);
  }
  console.log('[tutor-katex] up to date');
} else {
  writeFileSync(outFile, text);
  console.log(`[tutor-katex] wrote ${path.relative(root, outFile)} (${text.length} bytes)`);
}
